// One item per song sent by the PiKaraoke host's karaoke-tidy.py, each carrying the two Ollama requests.
// The prompt and schema are the ones evaluated in an 80-title labelled test:
// gpt-oss:20b and qwen3:30b-a3b are biased in OPPOSITE directions on Mandopop vs Cantopop, so
// acting only when they AGREE gave 55/55 right, 0 wrong moves. Self-reported confidence is useless
// as a gate (qwen3:30b said 0.95 on all 13 wrong answers and 66 of 67 right ones), so it is
// recorded but never trusted.
const SYSTEM = `You file karaoke videos for a household karaoke library. Given the title of a YouTube karaoke
video, decide which folder it belongs in, by the LANGUAGE THE SONG IS SUNG IN:
  K-pop     Korean-language songs
  Mandopop  Mandarin Chinese songs (mainland China, Taiwan, Singapore, Malaysia)
  Cantopop  Cantonese songs (mostly Hong Kong)
  English   English-language songs
  Other     anything else, or if you cannot tell
Use your knowledge of the artist and the song. Script is NOT decisive: Traditional Chinese characters
are used for both Taiwanese Mandarin songs and Cantonese songs, and K-pop is often written in English.
Ignore uploader clutter such as "(Karaoke Version)", "With Lyrics", "Original Key", "[TJ노래방]",
"Instrumental", "Official", "MV", channel names and emoji.
Return the artist and the song title in their native script (Chinese in SIMPLIFIED characters),
the artist's OFFICIAL English or romanised name ONLY if they are known by one (for example Jay Chou,
G.E.M., IU, Eason Chan); otherwise return an EMPTY artist_en, never a translation or an invented name,
the song's English title or romanisation (pinyin
for Chinese), and your confidence from 0 to 1. Return a low confidence rather than guess.`;
const SCHEMA = {
  type: 'object',
  properties: {
    genre: { type: 'string', enum: ['K-pop', 'Mandopop', 'Cantopop', 'English', 'Other'] },
    artist_native: { type: 'string' }, artist_en: { type: 'string' },
    title_native: { type: 'string' }, title_en: { type: 'string' },
    confidence: { type: 'number' },
  },
  required: ['genre', 'artist_native', 'artist_en', 'title_native', 'title_en', 'confidence'],
};
const body = (model, title, extra) => ({
  model, stream: false, format: SCHEMA,
  options: { temperature: 0, num_ctx: 4096 },
  messages: [{ role: 'system', content: SYSTEM }, { role: 'user', content: title }],
  ...extra,
});
const songs = ($input.first().json.body || {}).songs || [];
return songs.map(s => ({ json: {
  file: s.file, title: s.title,
  body_a: body('gpt-oss:20b', s.title, {}),
  body_b: body('qwen3:30b-a3b', s.title, { think: false }),
}}));

// Keep the song and model A's answer; a malformed answer becomes null (=> left for review).
const song = $('One item per song').item.json;
let a = null;
try { a = JSON.parse($json.message.content); } catch (e) { a = null; }
return { json: { ...song, a } };

// Decide the folder and build the house-format name. The PiKaraoke host validates everything again before moving.
//   both agree on a genre              -> that genre's folder
//   both say Chinese, but disagree     -> stays in the root for review (split: true)
//   anything else, or a malformed reply -> stays in the root, listed for review
const prev = $('Keep answer A').item.json;
let b = null;
try { b = JSON.parse($json.message.content); } catch (e) { b = null; }
const a = prev.a;
const ga = a && a.genre, gb = b && b.genre;
const CHINESE = ['Mandopop', 'Cantopop'];
let folder = null, reason, split = false;
if (!a || !b) reason = 'a model reply was malformed';
else if (ga === gb && ga !== 'Other') { folder = ga; reason = `both models: ${ga}`; }
else if (CHINESE.includes(ga) && CHINESE.includes(gb)) { split = true; reason = `Chinese split ${ga} vs ${gb}: left for review`; }
else if (ga === gb) reason = `both models: ${ga} (cannot tell)`;
else reason = `models disagree: ${ga} vs ${gb}`;

// Names: qwen3:30b-a3b's extraction (43/44 exact in the evaluation), gpt-oss's as fallback.
const src = (b && b.title_native) ? b : a;
const clean = s => (s || '').replace(/[\\/:*?"<>|]/g, '-').replace(/\s+/g, ' ').trim();
const hasNative = s => /[ㄱ-ㆎ가-힣一-鿿]/.test(s || '');
let name = null;
if (folder && src) {
  const ae = clean(src.artist_en), an = clean(src.artist_native);
  const tn = clean(src.title_native), te = clean(src.title_en);
  const artist = (ae && an && ae.toLowerCase() !== an.toLowerCase()) ? `${ae} ${an}` : (ae || an);
  let title;
  if (folder === 'English') title = te || tn;
  else title = (tn && te && hasNative(tn) && te.toLowerCase() !== tn.toLowerCase()) ? `${tn} (${te})` : (tn || te);
  if (artist && title) name = `${artist} - ${title}`.slice(0, 140);
}
if (folder && !name) { folder = null; split = false; reason += '; no usable name'; }
return { json: {
  file: prev.file, title: prev.title, folder, name, reason, split,
  genre_a: ga || null, genre_b: gb || null,
  confidence_a: a ? a.confidence : null, confidence_b: b ? b.confidence : null,
  // Raw fields: the PiKaraoke host rebuilds CHINESE names itself (OpenCC t2s + pypinyin), because the models keep
  // Traditional script and translate titles ('Fuji Mountain Below') instead of giving pinyin.
  artist_en: src ? clean(src.artist_en) : null, artist_native: src ? clean(src.artist_native) : null,
  title_native: src ? clean(src.title_native) : null, title_en: src ? clean(src.title_en) : null,
}};
